const C=document.getElementById('content'),M=document.getElementById('modal'),MC=document.getElementById('modalContent');
let records=[],user=null,demo=false,current='home',selected=today(),month=selected.slice(0,7),view='week',payPeriod='month',payGroup='Tutti',payMethod='Tutti',patientSort='az',patientSite='Tutti',patientPageSize='25',patientPage=1,archive=false,lastSync='',consentShare=null;
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function today(){return localDate(new Date())}function localDate(d){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}const addDay=(s,n)=>{const d=new Date(s+'T12:00');d.setDate(d.getDate()+n);return localDate(d)};
const money=x=>Number(x||0).toLocaleString('it-IT',{style:'currency',currency:'EUR'});const dateLabel=d=>new Date(d+'T12:00').toLocaleDateString('it-IT',{weekday:'short',day:'numeric',month:'long'});
const list=k=>records.filter(r=>r.kind===k);const get=id=>records.find(r=>r.id===id);const full=p=>p?[p.data.firstName,p.data.lastName].join(' '):'Paziente non trovato';const title=r=>r.data.personal?r.data.title:full(get(r.data.patientId));const rec=(kind,data,id)=>({id:id||crypto.randomUUID(),kind,data,version:get(id)?.version||0});
const btn=(text,action,cls='ghost')=>`<button type="button" class="${cls}" onclick="${action}">${text}</button>`;
const input=(name,label,value='',type='text',extra='')=>`<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;
const select=(name,label,options,value)=>`<label>${label}<select name="${name}">${options.map(o=>{const a=Array.isArray(o)?o:[o,o];return `<option value="${esc(a[0])}" ${a[0]===value?'selected':''}>${esc(a[1])}</option>`}).join('')}</select></label>`;
const check=(name,label,val)=>`<label class="check"><input type="checkbox" name="${name}" ${val?'checked':''}> ${label}</label>`;
function notice(s){const e=document.getElementById('notice');e.textContent=s;e.hidden=false;clearTimeout(notice.timer);notice.timer=setTimeout(()=>e.hidden=true,6500)}
async function api(action,body){const r=await fetch('/api/app?action='+action,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});let d;try{d=await r.json()}catch{throw Error('Il sito richiede la pubblicazione su Vercel con le funzioni server.')}if(!r.ok)throw Error(d.error||'Errore');return d}
async function sync(){try{if(!demo){const s=await api('state');records=s.records;user=s.user}lastSync=new Date().toLocaleTimeString('it-IT');render();notice(demo?'Demo aggiornata (dati temporanei)':'Dati aggiornati alle '+lastSync)}catch(e){notice(e.message)}}
async function save(items){if(demo){for(const r of items){if(r.kind==='appointments'&&!r.data.cancelled){if(records.some(a=>a.id!==r.id&&a.kind==='appointments'&&!a.data.cancelled&&a.data.start<r.data.end&&a.data.end>r.data.start))throw Error('Orario occupato');} }for(const r of items){const i=records.findIndex(x=>x.id===r.id);r.version++;if(i<0)records.push(r);else records[i]=r}}else await api('save',{items});if(!demo){const s=await api('state');records=s.records}render()}
function show(html){MC.innerHTML=html;M.classList.remove('hide');MC.querySelector('input,button,select')?.focus()}function closeM(){M.classList.add('hide')}
function form(title,html,saveFn){show(`<h2>${title}</h2><form class="form">${html}<p class="full error" role="alert"></p><button class="primary full">Salva</button></form>`);MC.querySelector('form').onsubmit=async e=>{e.preventDefault();const f=e.target,b=f.querySelector('button[type=submit],button.primary');b.disabled=true;try{await saveFn(Object.fromEntries(new FormData(f)),f);closeM()}catch(err){f.querySelector('.error').textContent=err.message}finally{b.disabled=false}}}
function page(p){current=p;document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===p));render()}
function events(day){return list('appointments').filter(r=>!r.data.cancelled&&localDate(new Date(r.data.start))<=day&&localDate(new Date(new Date(r.data.end).getTime()-1))>=day).sort((a,b)=>a.data.start.localeCompare(b.data.start))}
function rows(items){return items.length?items.map(r=>`<div class="appt" tabindex="0" role="button" onclick="appointment('${r.id}')" onkeydown="if(event.key==='Enter')appointment('${r.id}')"><span>${r.data.allDay?'Giorno':new Date(r.data.start).toLocaleTimeString('it-IT',{hour:'2-digit',minute:'2-digit'})}</span><div><b>${esc(title(r))}</b><small>${r.data.personal?'Impegno personale':`${esc(r.data.site)} · ${r.data.payment==='paid'?'Saldato':'Da saldare'} · ${money(r.data.fee)} ${r.data.invoice?'· Fattura':''}`}</small></div><span>›</span></div>`).join(''):'<p class="empty">Nessun appuntamento.</p>'}
function calendar(){const d=new Date(month+'-01T12:00'),offset=(d.getDay()+6)%7,n=new Date(d.getFullYear(),d.getMonth()+1,0).getDate();return `<div class="head"><h2>${d.toLocaleDateString('it-IT',{month:'long',year:'numeric'})}</h2><div>${btn('‹',"changeMonth(-1)")}${btn('›',"changeMonth(1)")}</div></div><div class="calendar-grid">${['L','M','M','G','V','S','D'].map(x=>`<span>${x}</span>`).join('')}${'<span></span>'.repeat(offset)}${Array.from({length:n},(_,i)=>{let day=month+'-'+String(i+1).padStart(2,'0'),es=events(day),rs=list('reminders').filter(r=>!r.data.done&&r.data.date===day);return `<button class="day ${day===today()?'today':''} ${day===selected?'selected':''}" data-day="${day}" onclick="selected='${day}';page('agenda')" onmouseenter="previewDay('${day}')" onfocus="previewDay('${day}')" aria-label="${esc(dateLabel(day))}, ${es.length} appuntamenti, ${rs.length} promemoria">${i+1}<small>${es.length||rs.length?'●':''}</small></button>`}).join('')}</div><div id="day-preview" class="day-preview" aria-live="polite">Passa su una data per vedere gli impegni e i promemoria.</div><div class="toolbar">${btn('Sincronizza','sync()')}${btn('Blocca orario',"appointment('',true)")}</div><small>Ultimo aggiornamento: ${lastSync||'—'}</small>`}
function previewDay(day){document.getElementById('day-preview').innerHTML=`<b>${esc(dateLabel(day))}</b>${events(day).map(r=>`<div>${esc(title(r))} · ${r.data.allDay?'Tutto il giorno':new Date(r.data.start).toLocaleTimeString('it-IT',{hour:'2-digit',minute:'2-digit'})}</div>`).join('')}${list('reminders').filter(r=>r.data.date===day&&!r.data.done).map(r=>`<div>□ ${esc(r.data.title)}</div>`).join('')||''}${!events(day).length&&!list('reminders').some(r=>r.data.date===day&&!r.data.done)?'<div>Nessun impegno</div>':''}`}
function changeMonth(n){const d=new Date(month+'-01T12:00');d.setMonth(d.getMonth()+n);month=localDate(d).slice(0,7);render()}
function home(){const ps=list('patients');C.innerHTML=`<section class="hero"><img class="hero-bird" src="assets/colibri.png" alt=""><div><h3>STUDIO ROCCHI</h3><small>PSICOLOGIA · SESSUOLOGIA · CRIMINOLOGIA</small><br><small>ASCOLTARE · COMPRENDERE · TRASFORMARE</small></div><p>Persone<br>relazioni<br>possibilità</p></section><div class="greeting"><div><h1>Il tuo studio, oggi</h1><small>${dateLabel(today())}</small></div><em>“La cura è anche organizzazione.”</em></div><div class="stats">${[[events(today()).filter(r=>!r.data.personal).length,'Appuntamenti oggi'],[ps.length,'Pazienti'],[ps.filter(r=>!list('documents').some(x=>x.data.patientId===r.id&&['consent-autograph','consent-online'].includes(x.data.documentType))).length,'Consensi da acquisire'],[list('appointments').filter(r=>!r.data.personal&&!r.data.cancelled&&r.data.payment==='due').length,'Pagamenti in sospeso']].map(([n,t])=>`<div class="stat"><b>${n}</b><small>${t}</small></div>`).join('')}</div><div class="dash"><div class="card"><div class="head"><h2>Agenda di oggi</h2>${btn('Vedi agenda',"page('agenda')")}</div>${rows(events(today()))}<div class="actions">${btn('＋ Nuovo appuntamento','appointment()','primary')}${btn('Appuntamento ricorrente',"appointment('',false,true)")}</div></div><div class="card">${calendar()}</div><div class="card"><div class="head"><h2>Promemoria</h2>${btn('Vedi tutti',"page('promemoria')")}</div>${reminders(false,true)}${btn('＋ Nuovo promemoria','reminder()','primary wide')}</div><div class="card recent"><h2>Pazienti recenti</h2>${ps.slice(-5).reverse().map(p=>btn(esc(full(p)),`patient('${p.id}')`)).join('')||'<p>Nessun paziente inserito.</p>'}</div><div class="card docs"><h2>Ultimi documenti</h2>${docRows(list('documents').slice(-4).reverse())}</div><div class="card quote"><blockquote>«Le persone<br>non sono problemi<br>da risolvere,<br>ma storie da comprendere.»</blockquote></div></div>`}
function inPeriod(date,period,day=selected){if(!date)return false;if(period==='day')return date===day;if(period==='month')return date.slice(0,7)===day.slice(0,7);const d=new Date(day+'T12:00'),start=addDay(day,-((d.getDay()+6)%7));return date>=start&&date<addDay(start,7)}
function agenda(){let days=[selected];if(view==='week'){const start=addDay(selected,-((new Date(selected+'T12:00').getDay()+6)%7));days=Array.from({length:7},(_,i)=>addDay(start,i))}C.innerHTML=`<h1>Agenda</h1><div class="toolbar">${btn('＋ Appuntamento','appointment()','primary')}${btn('Appuntamento ricorrente',"appointment('',false,true)")}${btn('Impegno personale',"appointment('',true)")}${select('view','Vista',[['day','Giornaliera'],['week','Settimanale'],['month','Mensile']],view)}${input('selected','Data',selected,'date')}</div><div class="agenda-layout"><div class="card">${calendar()}</div><div>${view==='month'?`<div class="card"><h2>${dateLabel(selected)}</h2>${rows(events(selected))}</div>`:days.map(day=>`<div class="card day-card"><h2>${dateLabel(day)}</h2>${rows(events(day))}</div>`).join('')}</div></div>`;C.querySelector('[name=view]').onchange=e=>{view=e.target.value;render()};C.querySelector('[name=selected]').onchange=e=>{if(e.target.value){selected=e.target.value;month=selected.slice(0,7);render()}}}
function appointment(id='',personal=false,repeat=false){const r=get(id),d=r?.data||{personal,start:selected+'T09:00',end:selected+'T10:00',fee:65,payment:'due',site:'Parma',mode:'In presenza'};personal=d.personal;const localTime=s=>{const t=new Date(s);return `${localDate(t)}T${String(t.getHours()).padStart(2,'0')}:${String(t.getMinutes()).padStart(2,'0')}`};
if(!personal&&!list('patients').length){notice('Crea prima la scheda del paziente.');return newPatient()}
form(repeat?'Appuntamento ricorrente':personal?'Impegno personale':r?'Modifica appuntamento':'Nuovo appuntamento',`${personal?input('title','Cosa farai',d.title||'','text','required'):select('patientId','Paziente',list('patients').map(p=>[p.id,full(p)]),d.patientId)}${input('start','Inizio',localTime(d.start),'datetime-local','required')}${input('end','Fine',localTime(d.end),'datetime-local','required')}${personal?check('allDay','Blocca intera giornata',d.allDay):`${select('site','Studio',['Parma','Modena','Online','Altro'],d.site)}${input('siteOther','Altro studio',d.siteOther)}${select('mode','Modalità',['In presenza','Online'],d.mode)}${input('fee','Tariffa (€)',d.fee,'number','min="0" step="0.01" required')}${select('payment','Pagamento',[['due','Da saldare'],['paid','Saldato']],d.payment)}${select('method','Metodo',['','Contanti','Bonifico','Carta credito','PayPal','Altro'],d.method)}${input('paymentNote','Note pagamento / altro metodo',d.paymentNote)}${input('paidDate','Data incasso',d.paidDate||today(),'date')}${check('invoice','Fattura emessa',d.invoice)}${input('invoiceNumber','Numero fattura',d.invoiceNumber)}${input('invoiceAmount','Importo fattura (€)',d.invoiceAmount??d.fee,'number','min="0" step="0.01"')}${check('invoicePaid','Fattura saldata',d.invoicePaid)}${check('lazzari','Avvocato Lazzari',d.lazzari)}${check('frigieri','Dott. Frigieri',d.frigieri)}${check('report','Relazione effettuata',d.report)}${check('completed','Visita eseguita',d.completed)}`}${repeat?`${select('interval','Ripeti ogni',[[7,'Settimana'],[14,'Due settimane'],[28,'Quattro settimane']].map(([a,b])=>[String(a),b]),'7')}${input('until','Fino al',addDay(selected,28),'date','required')}`:''}${input('note','Note',d.note)}${r?check('cancelled','Annullato (libera l’orario)',d.cancelled):''}`,async(v,f)=>{const checks=['allDay','invoice','invoicePaid','lazzari','frigieri','report','completed','cancelled'];const next={...d,...v,personal};checks.forEach(k=>next[k]=!!f.elements[k]?.checked);if(personal&&next.allDay){next.start=v.start.slice(0,10)+'T00:00';next.end=addDay(v.start.slice(0,10),1)+'T00:00'}if(new Date(next.end)<=new Date(next.start))throw Error('La fine deve essere successiva all’inizio');if(!personal&&v.site==='Altro'&&!v.siteOther.trim())throw Error('Specifica lo studio');next.fee=personal?0:Number(v.fee);next.invoiceAmount=Number(v.invoiceAmount||0);next.payment=personal?'due':v.payment;if(!personal&&next.payment==='paid'&&(!v.method||!v.paidDate))throw Error('Specifica metodo e data incasso');if(v.method==='Altro'&&!v.paymentNote.trim())throw Error('Specifica il metodo di pagamento');next.start=new Date(next.start).toISOString();next.end=new Date(next.end).toISOString();const items=[rec('appointments',next,id)];if(repeat){if(v.until<v.start.slice(0,10))throw Error('La data finale precede l’inizio');for(let i=Number(v.interval);;i+=Number(v.interval)){const a=new Date(next.start),b=new Date(next.end);a.setDate(a.getDate()+i);b.setDate(b.getDate()+i);if(localDate(a)>v.until)break;if(items.length>=100)throw Error('Massimo 100 ricorrenze');items.push(rec('appointments',{...next,start:a.toISOString(),end:b.toISOString()}))}}await save(items);notice('Appuntamento salvato')});
if(!personal&&!r){const f=MC.querySelector('form');f.elements.patientId.onchange=()=>{const p=get(f.elements.patientId.value).data;f.elements.fee.value=p.fee??65;f.elements.invoiceAmount.value=p.fee??65;f.elements.site.value=p.site||'Parma';f.elements.mode.value=p.mode||'In presenza'};f.elements.patientId.onchange()}}
function reminders(done,short=false){let a=list('reminders').filter(r=>!!r.data.done===done);if(short)a=a.slice(0,5);return a.map(r=>`<label class="todo"><input type="checkbox" ${done?`class="archive-select" value="${r.id}"`:`onchange="completeReminder('${r.id}')"`}><span>${done?'<s>':''}${esc(r.data.title)}${done?'</s>':''}<small>${r.data.date||''}</small></span>${done?'':`<button type="button" class="tiny" onclick="event.preventDefault();reminder('${r.id}')">✎</button>`}</label>`).join('')||'<p class="empty">Nessun promemoria.</p>'}
function reminder(id){const d=get(id)?.data||{};form('Promemoria',input('title','Cosa ricordare',d.title,'text','required')+input('date','Data',d.date||selected,'date'),v=>save([rec('reminders',{...d,...v,done:!!d.done},id)]))}
async function completeReminder(id){try{const r=get(id);await save([{...r,data:{...r.data,done:true}}])}catch(e){notice(e.message);render()}}
async function deleteReminders(){const ids=[...C.querySelectorAll('.archive-select:checked')].map(e=>e.value);if(!ids.length)return notice('Seleziona almeno un promemoria');if(!confirm(`Eliminare ${ids.length} promemoria archiviati?`))return;try{if(demo)records=records.filter(r=>!ids.includes(r.id));else await api('delete-reminders',{ids});await sync()}catch(e){notice(e.message)}}
const fields=[['firstName','Nome'],['lastName','Cognome'],['taxCode','Codice fiscale'],['birthDate','Data di nascita','date'],['birthPlace','Luogo di nascita'],['address','Via e numero civico'],['postalCode','CAP'],['city','Comune'],['province','Provincia'],['country','Nazione'],['email','Email','email'],['phone','Telefono','tel'],['startDate','Inizio terapia','date'],['fee','Tariffa (€)','number']];
function newPatient(id){const d=get(id)?.data||{country:'Italia',fee:65,site:'Parma',mode:'In presenza'};form(id?'Modifica anagrafica':'Nuovo paziente',fields.map(([n,l,t])=>input(n,l,d[n]??'',t||'text',['firstName','lastName'].includes(n)?'required':n==='fee'?'min="0" step="0.01"':'')).join('')+select('site','Studio',['Parma','Modena','Online','Altro'],d.site)+input('siteOther','Altro studio',d.siteOther)+select('mode','Modalità',['In presenza','Online'],d.mode)+check('couple','Viene in coppia',d.couple)+select('partnerId','Collega paziente',[['','Nessun collegamento'],...list('patients').filter(p=>p.id!==id).map(p=>[p.id,full(p)])],d.partnerId)+input('newPartnerFirst','Oppure: nome nuovo partner')+input('newPartnerLast','Cognome nuovo partner'),async(v,f)=>{v.couple=f.elements.couple.checked;v.fee=Number(v.fee||0);if(v.site==='Altro'&&!v.siteOther.trim())throw Error('Specifica lo studio');v.taxCode=v.taxCode.trim().toUpperCase();if(v.taxCode&&list('patients').some(p=>p.id!==id&&p.data.taxCode===v.taxCode))throw Error('Codice fiscale già presente');let main=rec('patients',{...d,...v},id),items=[];if(v.couple&&v.newPartnerFirst&&v.newPartnerLast){if(v.partnerId)throw Error('Scegli un partner esistente oppure creane uno nuovo');const p=rec('patients',{firstName:v.newPartnerFirst,lastName:v.newPartnerLast,couple:true,partnerId:main.id,fee:v.fee,site:v.site,mode:v.mode,consent:false});v.partnerId=p.id;items.push(p)}if(v.couple&&!v.partnerId)throw Error('Collega un paziente o inserisci nome e cognome del partner');if(v.couple&&v.partnerId){const p=get(v.partnerId);if(p?.data.partnerId&&p.data.partnerId!==main.id)throw Error('Questo paziente è già collegato a un’altra coppia');if(p)items.push({...p,data:{...p.data,couple:true,partnerId:main.id}})}const old=get(id)?.data.partnerId;if(old&&(!v.couple||old!==v.partnerId)){const p=get(old);if(p?.data.partnerId===id)items.push({...p,data:{...p.data,couple:false,partnerId:''}})}if(!v.couple)main.data.partnerId='';delete main.data.newPartnerFirst;delete main.data.newPartnerLast;items.push(main);await save(items)})}
function patientsPage(){const sites=[...new Set(list('patients').map(p=>p.data.site==='Altro'?(p.data.siteOther||'Altro'):p.data.site).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'it'));let items=list('patients').filter(p=>patientSite==='Tutti'||(p.data.site==='Altro'?(p.data.siteOther||'Altro'):p.data.site)===patientSite).sort((a,b)=>full(a).localeCompare(full(b),'it',{sensitivity:'base'}));if(patientSort==='za')items.reverse();const total=items.length,size=patientPageSize==='all'?Math.max(total,1):Number(patientPageSize),pages=Math.max(1,Math.ceil(total/size));patientPage=Math.min(patientPage,pages);const visible=patientPageSize==='all'?items:items.slice((patientPage-1)*size,patientPage*size);C.innerHTML=`<h1>Pazienti</h1><div class="toolbar">${btn('＋ Nuovo paziente','newPatient()','primary')}${btn('Esporta XLS','exportPatients()')}${btn('Importa XLS / XLSX','importPatients()')}</div><div class="toolbar filters">${select('patientSort','Ordine',[['az','Alfabetico A–Z'],['za','Alfabetico Z–A']],patientSort)}${select('patientSite','Studio',[['Tutti','Tutti gli studi'],...sites.map(x=>[x,x])],patientSite)}${select('patientPageSize','Pazienti per pagina',[['25','25'],['30','30'],['100','100'],['all','Tutti']],patientPageSize)}<small>${total} pazienti</small></div><div class="card table-wrap"><table class="table"><thead><tr><th>Paziente</th><th>Studio</th><th>Modalità</th><th>Tariffa</th><th>Consenso</th><th>Coppia</th></tr></thead><tbody>${visible.map(p=>`<tr><td>${btn(esc(full(p)),`patient('${p.id}')`)}</td><td>${esc(p.data.site==='Altro'?p.data.siteOther:p.data.site)}</td><td>${esc(p.data.mode)}</td><td>${money(p.data.fee)}</td><td>${list('documents').some(x=>x.data.patientId===p.id&&x.data.documentType==='consent-online')?'Online acquisito':list('documents').some(x=>x.data.patientId===p.id&&x.data.documentType==='consent-autograph')?'Copia firma autografa acquisita':p.data.consent?'Precedente indicazione manuale':'Da acquisire'}</td><td>${p.data.couple?'Sì':'No'}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">Nessun paziente per questo studio.</td></tr>'}</tbody></table>${patientPageSize!=='all'&&pages>1?`<div class="pagination">${btn('← Precedente',`patientPage=Math.max(1,patientPage-1);render()`)}<span>Pagina ${patientPage} di ${pages}</span>${btn('Successiva →',`patientPage=Math.min(${pages},patientPage+1);render()`)}</div>`:''}</div>`;C.querySelector('[name=patientSort]').onchange=e=>{patientSort=e.target.value;patientPage=1;render()};C.querySelector('[name=patientSite]').onchange=e=>{patientSite=e.target.value;patientPage=1;render()};C.querySelector('[name=patientPageSize]').onchange=e=>{patientPageSize=e.target.value;patientPage=1;render()}}
function docRows(docs){return docs.map(r=>`<div class="doc">▤ ${btn(esc(r.data.name),`downloadDoc('${r.id}')`)} ${r.data.documentType==='consent-autograph'?`<small>Consenso · firma autografa (copia PDF) · ricevuto ${esc(r.data.receivedDate)} · SHA-256 ${esc(r.data.sha256?.slice(0,12)||'—')}…</small>`:r.data.documentType==='consent-online'?`<small>Consenso online · confermato ${esc(new Date(r.data.acceptedAt).toLocaleString('it-IT'))} · versione ${esc(r.data.consentVersion)} · evidenza ${esc(r.data.evidenceHash?.slice(0,12)||'—')}…</small>`:''}</div>`).join('')||'<p class="empty">Nessun documento.</p>'}
function consentStatus(id,d){const docs=list('documents').filter(r=>r.data.patientId===id&&['consent-autograph','consent-online'].includes(r.data.documentType)).sort((a,b)=>String(b.data.acceptedAt||b.data.uploadedAt).localeCompare(String(a.data.acceptedAt||a.data.uploadedAt)));if(docs.length){const x=docs[0];return x.data.documentType==='consent-online'?'Consenso online confermato il '+esc(new Date(x.data.acceptedAt).toLocaleString('it-IT')):'Copia PDF con firma autografa ricevuta il '+esc(x.data.receivedDate)}return d.consent?'Precedente indicazione manuale del '+esc(d.consentDate||'data non indicata')+'; documento non presente':'Da acquisire'}
function uploadConsent(id){if(demo){notice('Disponibile dopo il collegamento dell’archivio online');return}show(`<h2>Carica consenso con firma autografa</h2><p>Il PDF deve contenere il modulo firmato a penna dal paziente. Questa copia non è una firma digitale.</p><form class="form"><label class="full">PDF firmato<input name="file" type="file" accept="application/pdf,.pdf" required></label>${input('receivedDate','Data di ricezione',today(),'date','required')}${select('receivedVia','Ricevuto tramite',[['email','Email'],['whatsapp','WhatsApp'],['mano','Consegna a mano'],['altro','Altro']],'email')}<p class="full error" role="alert"></p><button class="primary full">Archivia nella scheda e in Documenti</button></form>`);MC.querySelector('form').onsubmit=async e=>{e.preventDefault();const f=e.target,b=f.querySelector('button'),file=f.elements.file.files[0];b.disabled=true;try{if(!file||file.size>3*1024*1024)throw Error('Seleziona un PDF entro 3 MB');const base64=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result.split(',')[1]);reader.onerror=reject;reader.readAsDataURL(file)});await api('upload',{patientId:id,name:file.name,base64,documentType:'consent-autograph',receivedDate:f.elements.receivedDate.value,receivedVia:f.elements.receivedVia.value});const state=await api('state');records=state.records;closeM();patient(id);notice('Consenso archiviato nella scheda e in Documenti')}catch(err){f.querySelector('.error').textContent=err.message}finally{b.disabled=false}}}
async function generateConsentLink(id){
 if(demo){notice('Disponibile dopo il collegamento dell’archivio online');return}
 try{
  const r=await api('consent-create',{patientId:id});
  const p=get(id),name=full(p),msg=`Ciao ${p.data.firstName||''}, ti invio il link per leggere e confermare il consenso informato dello Studio Rocchi. Il link scade tra 7 giorni: ${r.url}`;
  consentShare={url:r.url,name,msg};
  show(`<h2>Link consenso informato</h2><p>Invialo esclusivamente alla persona corretta. Il link è personale, monouso e scade il <b>${esc(new Date(r.expiresAt).toLocaleString('it-IT'))}</b>.</p><div class="consent-link-box" id="consent-link">${esc(r.url)}</div><div class="consent-actions">${btn('Copia link','copyCurrentConsentLink()','primary')}${btn('WhatsApp','shareCurrentConsentWhatsApp()')}${btn('Email','shareCurrentConsentEmail()')}</div><p><small>Il paziente compila il modulo online; al salvataggio viene generato un PDF archiviato automaticamente nella scheda e in Documenti.</small></p>`)
 }catch(e){notice(e.message)}
}
async function copyCurrentConsentLink(){if(!consentShare)return;try{await navigator.clipboard.writeText(consentShare.url);notice('Link copiato')}catch{prompt('Copia questo link',consentShare.url)}}
function shareCurrentConsentWhatsApp(){if(consentShare)window.open('https://wa.me/?text='+encodeURIComponent(consentShare.msg),'_blank','noopener')}
function shareCurrentConsentEmail(){if(consentShare)location.href='mailto:?subject='+encodeURIComponent('Consenso informato Studio Rocchi - '+consentShare.name)+'&body='+encodeURIComponent(consentShare.msg)}
async function publicConsent(token){
 const pub=document.getElementById('public-consent'),auth=document.getElementById('auth'),shell=document.querySelector('.shell');auth.hidden=true;shell.hidden=true;pub.hidden=false;pub.innerHTML='<div class="consent-wrap"><div class="card"><h1>Modulo prestazione professionale</h1><p>Caricamento…</p></div></div>';
 try{
  const r=await fetch('/api/app?action=consent-view&token='+encodeURIComponent(token),{cache:'no-store'}),d=await r.json();if(!r.ok)throw Error(d.error||'Link non disponibile');const p=d.patient,m=d.model;
  const radio=(name,value,label,checked=false)=>`<label class="check consent-choice"><input type="radio" name="${name}" value="${esc(value)}" ${checked?'checked':''} required> ${esc(label)}</label>`;
  pub.innerHTML=`<div class="consent-wrap"><div class="card consent-form-card"><div class="consent-letterhead"><img src="assets/logo.png" width="105" alt="Studio Rocchi"><div><h1>${esc(m.title)}</h1><p><b>${esc(m.subtitle)}</b></p><p>${esc(m.professional)}</p><p>${esc(m.offices)}</p><p>${esc(m.contacts)}</p></div></div><div class="warning-box">Compila il modulo in ogni sua parte. Al salvataggio verrà creato un PDF, archiviato automaticamente nello Studio Rocchi e disponibile anche per il download e la stampa.</div><form id="public-consent-form" class="form consent-form">${input('fullName','Nome e cognome',[p.firstName,p.lastName].filter(Boolean).join(' '),'text','required autocomplete="name"')}${input('birthPlace','Luogo di nascita',p.birthPlace,'text','required')}${input('birthDate','Data di nascita',p.birthDate,'date','required')}${input('residenceCity','Comune di residenza',p.residenceCity,'text','required')}${input('address','Via e numero civico',p.address,'text','required')}${input('taxCode','Codice fiscale',p.taxCode,'text','required maxlength="32"')}${input('sdiPec','SDI / PEC per fatturazione (se necessario)','','text')}<fieldset class="full consent-fieldset"><legend>1) Prestazione</legend>${m.services.map(x=>radio('service',x,x,false)).join('')}<p>La prestazione potrà includere colloqui e, se necessario, test/strumenti psicodiagnostici.</p></fieldset><fieldset class="full consent-fieldset"><legend>2) Modalità</legend>${m.modes.map(x=>radio('mode',x,x,p.mode===x)).join('')}<p>Durata e obiettivi vengono concordati e possono essere rimodulati nel corso del percorso.</p></fieldset><section class="full consent-section"><h2>3) Interruzione</h2><p>Il/la cliente può interrompere il percorso in qualsiasi momento comunicandolo alla professionista.</p><p>La professionista può proporre l’interruzione qualora non vi siano benefici ragionevolmente prevedibili.</p></section><section class="full consent-section"><h2>4) Riservatezza</h2><p>La professionista è tenuta al segreto professionale secondo Codice Deontologico e normativa vigente.</p></section><section class="full consent-section"><h2>5) Appuntamenti e disdette</h2><p>Il/la cliente si impegna al rispetto degli orari concordati.</p><p>In caso di disdetta con meno di 24 ore, la seduta è da considerarsi dovuta, salvo comprovata urgenza.</p></section><section class="full consent-section"><h2>6) Compenso</h2><p>Seduta individuale: Euro 65,00 + 2% ENPAP</p><p>Seduta di coppia: Euro 90,00 + 2% ENPAP</p><p>Il compenso non può essere condizionato all’esito della prestazione. Per la detraibilità sanitaria è richiesto pagamento tracciabile.</p></section><section class="full consent-section"><h2>7) Trattamento dati personali (GDPR)</h2><p>I dati personali e quelli relativi alla salute verranno trattati esclusivamente per finalità professionali, con adeguate misure di sicurezza e nel rispetto della normativa vigente (Reg. UE 2016/679 e D.Lgs. 101/2018).</p></section><section class="full consent-section"><h2>8) Assicurazione professionale</h2><p>Polizza RC professionale UNIPOL SAI n. 1/2545/122/198921942.</p></section><fieldset class="full consent-fieldset"><legend>CONSENSI (barrare)</legend><label class="check"><input name="consentProfessional" type="checkbox" required> Acconsento alla prestazione professionale</label><label class="check"><input name="consentPrivacy" type="checkbox" required> Acconsento al trattamento dei dati personali e dei dati relativi alla salute</label><label class="check"><input name="consentTs" type="checkbox"> (se prestazione sanitaria) Acconsento all’invio dei dati al Sistema Tessera Sanitaria</label></fieldset>${input('placeDate','Luogo e data','','text','required placeholder="es. Parma, 25/09/2026"')}${input('clientSignature','Firma Cliente - digitare nome e cognome',[p.firstName,p.lastName].filter(Boolean).join(' '),'text','required')}<div class="full signature-note"><b>Firma Professionista</b><div class="signature-line"></div><small>Il PDF verrà generato con il nominativo digitato dal cliente. Non costituisce firma digitale qualificata; il documento può essere stampato per la firma autografa.</small></div><p class="full"><small>Versione modulo: ${esc(d.version)}</small></p><p class="full error" role="alert"></p><button class="primary full">Salva e genera PDF</button></form></div></div>`;
  document.getElementById('public-consent-form').onsubmit=async e=>{e.preventDefault();const f=e.target,b=f.querySelector('button');b.disabled=true;try{const body=Object.fromEntries(new FormData(f));body.token=token;body.consentProfessional=f.elements.consentProfessional.checked;body.consentPrivacy=f.elements.consentPrivacy.checked;body.consentTs=f.elements.consentTs.checked;const rr=await fetch('/api/app?action=consent-submit',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}),dd=await rr.json();if(!rr.ok)throw Error(dd.error||'Impossibile registrare il consenso');pub.innerHTML=`<div class="consent-wrap"><div class="card success-box"><img src="assets/logo.png" width="100" alt="Studio Rocchi"><h1>Modulo salvato</h1><p>Il PDF è stato generato il <b>${esc(new Date(dd.acceptedAt).toLocaleString('it-IT'))}</b> ed è già archiviato nella scheda del paziente e nella sezione Documenti.</p><p><a class="primary download-consent" href="${esc(dd.downloadUrl)}" target="_blank" rel="noopener">Scarica il PDF</a></p><p>Puoi stamparlo e conservarne una copia.</p></div></div>`}catch(err){f.querySelector('.error').textContent=err.message}finally{b.disabled=false}}
 }catch(e){pub.innerHTML=`<div class="consent-wrap"><div class="card"><h1>Link non disponibile</h1><p>${esc(e.message)}</p><p>Chiedi allo Studio Rocchi un nuovo link.</p></div></div>`}
}


function patient(id){const p=get(id),d=p.data;const visits=list('appointments').filter(r=>r.data.patientId===id).sort((a,b)=>b.data.start.localeCompare(a.data.start));show(`<h2>${esc(full(p))}</h2><div class="toolbar">${btn('Modifica anagrafica',`newPatient('${id}')`)}${d.couple&&get(d.partnerId)?btn('Partner: '+esc(full(get(d.partnerId))),`patient('${d.partnerId}')`):''}</div><dl>${fields.map(([k,l])=>`<dt>${l}</dt><dd>${esc(d[k]??'—')}</dd>`).join('')}<dt>Studio / modalità</dt><dd>${esc(d.site==='Altro'?d.siteOther:d.site)} · ${esc(d.mode)}</dd><dt>Consenso</dt><dd>${consentStatus(id,d)}</dd></dl><h3>Storico visite</h3><p>Le visite passate sono recuperate automaticamente. “Eseguita” conferma l’effettivo svolgimento.</p>${history(visits.filter(r=>new Date(r.data.start)<new Date()))}<h3>Prossimi appuntamenti</h3>${rows(visits.filter(r=>new Date(r.data.start)>=new Date()&&!r.data.cancelled))}<h3>Avvocato Lazzari</h3>${history(visits.filter(r=>r.data.lazzari))}<h3>Dott. Frigieri</h3>${history(visits.filter(r=>r.data.frigieri))}<h3>Consenso informato</h3><p>Puoi generare un link personale che apre il modulo completo di consenso. Al salvataggio viene creato un PDF, archiviato nella scheda e in Documenti. Resta disponibile anche il caricamento di una copia firmata a penna.</p><div class="toolbar">${btn('Genera link consenso online',`generateConsentLink('${id}')`,'primary')}${btn('Carica consenso con firma autografa',`uploadConsent('${id}')`)}</div><h3>Documenti e immagini</h3>${docRows(list('documents').filter(r=>r.data.patientId===id))}<label>Carica allegati (massimo 3 MB ciascuno)<input type="file" multiple accept=".pdf,.doc,.docx,.xls,.xlsx,.png,.jpg,.jpeg,.gif,.webp,.txt,.odt" onchange="uploadDocs('${id}',this.files)"></label>`)}
function history(rs){return rs.length?`<div class="table-wrap"><table class="table"><tr><th>Data / visita</th><th>Tariffa</th><th>Relazione</th><th>Fattura</th><th>Saldo</th></tr>${rs.map(r=>`<tr><td>${btn(dateLabel(localDate(new Date(r.data.start))),`appointment('${r.id}')`)}<small>${r.data.cancelled?'Annullata':r.data.completed?'Eseguita':'Da confermare'}</small></td><td>${money(r.data.fee)}</td><td>${r.data.report?'Effettuata':'Non effettuata'}</td><td>${r.data.invoice?esc(r.data.invoiceNumber||'Emessa')+' · '+money(r.data.invoiceAmount)+' · '+(r.data.invoicePaid?'Saldata':'Da saldare'):'Non emessa'}</td><td>${r.data.payment==='paid'?'Saldato':'Da saldare'}</td></tr>`).join('')}</table></div>`:'<p class="empty">Nessuna visita.</p>'}
async function uploadDocs(id,files){try{if(demo)throw Error('Caricamento disponibile dopo il collegamento dell’archivio online');for(const file of files){if(file.size>3*1024*1024)throw Error(file.name+': supera 3 MB');const base64=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result.split(',')[1]);reader.onerror=reject;reader.readAsDataURL(file)});await api('upload',{patientId:id,name:file.name,base64})}await sync();patient(id);notice('Allegati caricati')}catch(e){notice(e.message)}}
async function downloadDoc(id){try{const s=await api('download',{id});const a=document.createElement('a');a.href=s.url;a.target='_blank';a.rel='noopener';a.download=get(id).data.name;a.click()}catch(e){notice(e.message)}}
const exportFields=[...fields,['site','Studio'],['siteOther','Altro studio'],['mode','Modalità'],['consent','Consenso firmato'],['consentDate','Data consenso'],['couple','In coppia'],['partnerId','ID partner']];
function exportPatients(){const rows=list('patients').map(p=>Object.fromEntries([['ID',p.id],...exportFields.map(([k,l])=>[l,p.data[k]??''])]));const ws=XLSX.utils.json_to_sheet(rows,{header:['ID',...exportFields.map(x=>x[1])]});const wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,ws,'Pazienti');XLSX.writeFile(wb,'pazienti.xls',{bookType:'biff8'})}
function importPatients(){show(`<h2>Importa pazienti</h2><p>Usa le intestazioni del file esportato. Nome e Cognome sono obbligatori. Le righe con ID o codice fiscale già presenti aggiornano la scheda corrispondente.</p><input type="file" accept=".xls,.xlsx" id="import-file"><div id="import-preview"></div>`);document.getElementById('import-file').onchange=async e=>{try{const wb=XLSX.read(await e.target.files[0].arrayBuffer(),{type:'array',cellDates:true});const rows=XLSX.utils.sheet_to_json(wb.Sheets[wb.SheetNames[0]],{defval:''});if(!rows.length||rows.length>500)throw Error('Importa da 1 a 500 pazienti per volta');const seen=new Set(),items=rows.map((row,i)=>{const d={};for(const [k,l]of exportFields){let v=row[l];if(v instanceof Date)v=localDate(v);if(['consent','couple'].includes(k))v=[true,1,'1','true','Sì','Si','si','sì'].includes(v);d[k]=v??''}d.firstName=String(d.firstName);d.lastName=String(d.lastName);d.taxCode=String(d.taxCode).trim().toUpperCase();if(!String(d.firstName).trim()||!String(d.lastName).trim())throw Error(`Riga ${i+2}: nome e cognome mancanti`);const old=get(row.ID)||list('patients').find(p=>d.taxCode&&p.data.taxCode===d.taxCode);const id=old?.id||(/^[0-9a-f-]{36}$/i.test(row.ID)?row.ID:crypto.randomUUID());const key=d.taxCode||id;if(seen.has(key))throw Error('Doppione nel file alla riga '+(i+2));seen.add(key);d.fee=Number(String(d.fee||0).replace(',','.'));if(!Number.isFinite(d.fee)||d.fee<0)throw Error('Tariffa non valida alla riga '+(i+2));return rec('patients',{...old?.data,...d},id)});for(const p of items){if(p.data.couple&&!items.some(q=>q.id===p.data.partnerId)&&!get(p.data.partnerId))throw Error('Collegamento coppia non trovato per '+full(p))}document.getElementById('import-preview').innerHTML=`<p>${items.length} schede: ${items.filter(x=>get(x.id)).length} aggiornamenti, ${items.filter(x=>!get(x.id)).length} nuove.</p><p>${items.slice(0,5).map(p=>esc(full(p))).join('<br>')}</p><button class="primary" id="confirm-import">Conferma importazione</button>`;document.getElementById('confirm-import').onclick=async()=>{try{await save(items);closeM();notice('Importazione completata')}catch(err){notice(err.message)}}}catch(err){document.getElementById('import-preview').textContent=err.message}}}
function paymentMatch(r){const d=r.data;return payGroup==='Tutti'||payGroup==='Lazzari'&&d.lazzari||payGroup==='Frigieri'&&d.frigieri||payGroup===d.site}
function paymentEntry(){if(!list('patients').length){notice('Crea prima la scheda del paziente.');return newPatient()}const ps=[...list('patients')].sort((a,b)=>full(a).localeCompare(full(b),'it'));form('Registra pagamento visita',`${select('patientId','Paziente',ps.map(p=>[p.id,full(p)]))}${input('visitDate','Data della visita',selected,'date','required')}${select('site','Studio',['Parma','Modena','Online','Altro'],'Parma')}${input('siteOther','Altro studio')}${input('fee','Importo (€)',65,'number','min="0" step="0.01" required')}${select('method','Metodo di pagamento',['Contanti','Bonifico','Carta credito','PayPal','Altro'],'Contanti')}${input('paymentNote','Note / altro metodo')}${input('paidDate','Data del pagamento',today(),'date','required')}${check('invoice','Fattura emessa',false)}<label id="invoice-number-wrap" hidden>Numero fattura<input name="invoiceNumber"></label>`,async(v,f)=>{if(v.site==='Altro'&&!v.siteOther.trim())throw Error('Specifica lo studio');if(v.method==='Altro'&&!v.paymentNote.trim())throw Error('Specifica il metodo di pagamento');const invoice=f.elements.invoice.checked;if(invoice&&!v.invoiceNumber.trim())throw Error('Indica il numero della fattura');const start=new Date(v.visitDate+'T12:00'),end=new Date(v.visitDate+'T13:00');await save([rec('appointments',{patientId:v.patientId,start:start.toISOString(),end:end.toISOString(),site:v.site,siteOther:v.siteOther,mode:v.site==='Online'?'Online':'In presenza',fee:Number(v.fee),payment:'paid',method:v.method,paymentNote:v.paymentNote,paidDate:v.paidDate,invoice,invoiceNumber:invoice?v.invoiceNumber:'',invoiceAmount:Number(v.fee),invoicePaid:invoice,completed:true,personal:false,directPayment:true})]);notice(invoice?'Pagamento e fattura registrati':'Pagamento registrato · fattura da emettere')});const f=MC.querySelector('form'),toggle=()=>document.getElementById('invoice-number-wrap').hidden=!f.elements.invoice.checked;f.elements.invoice.onchange=toggle;f.elements.patientId.onchange=()=>{const p=get(f.elements.patientId.value)?.data;if(!p)return;f.elements.site.value=p.site||'Parma';f.elements.siteOther.value=p.siteOther||'';f.elements.fee.value=p.fee??65};f.elements.patientId.onchange();toggle()}
function payments(){const all=list('appointments').filter(r=>!r.data.personal&&!r.data.cancelled&&paymentMatch(r));const paid=all.filter(r=>r.data.payment==='paid'&&inPeriod(r.data.paidDate,payPeriod));const dues=all.filter(r=>r.data.payment!=='paid'&&inPeriod(localDate(new Date(r.data.start)),payPeriod));const invoicesDue=list('appointments').filter(r=>!r.data.personal&&!r.data.cancelled&&r.data.payment==='paid'&&!r.data.invoice).sort((a,b)=>(b.data.paidDate||'').localeCompare(a.data.paidDate||''));const filtered=paid.filter(r=>payMethod==='Tutti'||r.data.method===payMethod);const sum=a=>a.reduce((t,r)=>t+Math.round(Number(r.data.fee)*100),0)/100;C.innerHTML=`<div class="head"><h1>Pagamenti</h1>${btn('＋ Registra pagamento','paymentEntry()','primary')}</div><div class="toolbar">${select('period','Periodo',[['day','Giornaliero'],['week','Settimanale'],['month','Mensile']],payPeriod)}${input('day','Data di riferimento',selected,'date')}${select('group','Visualizza',['Tutti','Lazzari','Parma','Modena','Frigieri','Online'],payGroup)}${select('method','Metodo',['Tutti','Contanti','Bonifico','Carta credito','PayPal','Altro'],payMethod)}</div><div class="stats"><div class="stat"><b>${money(sum(paid))}</b><small>Incassato nel periodo</small></div><div class="stat"><b>${money(sum(dues))}</b><small>Da saldare · visite nel periodo</small></div></div><p>Gli incassi seguono la data di pagamento; il dovuto segue la data della visita. I filtri per inviante e studio possono includere le stesse visite e non vanno sommati tra loro.</p><div class="toolbar">${['Contanti','Bonifico','Carta credito','PayPal','Altro'].map(m=>`<div class="card"><small>${m}</small><h3>${money(sum(paid.filter(r=>r.data.method===m)))}</h3></div>`).join('')}</div><div class="card invoice-box"><div class="head"><h2>Fatture da emettere</h2><b>${invoicesDue.length}</b></div>${invoicesDue.length?`<table class="table"><tr><th>Data visita</th><th>Paziente</th><th>Studio</th><th>Importo</th><th></th></tr>${invoicesDue.map(r=>`<tr><td>${esc(localDate(new Date(r.data.start)))}</td><td>${esc(title(r))}</td><td>${esc(r.data.site==='Altro'?r.data.siteOther:r.data.site)}</td><td>${money(r.data.fee)}</td><td>${btn('Apri',`appointment('${r.id}')`)}</td></tr>`).join('')}</table>`:'<p class="empty">Nessuna fattura da emettere.</p>'}</div><div class="card table-wrap"><h2>Dettaglio incassi · ${money(sum(filtered))}</h2><table class="table"><tr><th>Data incasso</th><th>Paziente</th><th>Studio</th><th>Metodo</th><th>Importo</th><th>Fattura</th><th>Note</th></tr>${filtered.map(r=>`<tr><td>${esc(r.data.paidDate)}</td><td>${btn(esc(title(r)),`appointment('${r.id}')`)}</td><td>${esc(r.data.site==='Altro'?r.data.siteOther:r.data.site)}</td><td>${esc(r.data.method)}</td><td>${money(r.data.fee)}</td><td>${r.data.invoice?'N. '+esc(r.data.invoiceNumber||'—'):'Da emettere'}</td><td>${esc(r.data.paymentNote)}</td></tr>`).join('')}</table><h2>Da saldare</h2>${rows(dues)}</div>`;for(const [name,set] of [['period',v=>payPeriod=v],['day',v=>selected=v],['group',v=>payGroup=v],['method',v=>payMethod=v]])C.querySelector(`[name=${name}]`).onchange=e=>{if(e.target.value){set(e.target.value);render()}}}
async function accessPage(){C.innerHTML='<h1>Accessi</h1>';if(user.role!=='admin'){C.innerHTML+='<p>La gestione degli accessi è riservata agli amministratori.</p>';return}try{const users=demo?[user]:await api('users');if(current!=='accessi')return;C.innerHTML+=`<p>Amministratori: gestione completa, inclusi gli accessi. Operatori: gestione di agenda, pazienti, documenti e pagamenti.</p>${btn('＋ Nuovo accesso','editUser()','primary')}<div class="card">${users.map(u=>`<div class="user-row">${esc(u.email)} · ${u.role==='admin'?'Amministratore':'Operatore'} · ${u.active?'Attivo':'Disabilitato'} ${u.id!==user.id?btn('Modifica',`editUser('${u.id}','${u.role}',${u.active})`):'(tu)'}</div>`).join('')}</div>`}catch(e){notice(e.message)}}
function editUser(id='',role='operator',active=true){form(id?'Modifica accesso':'Nuovo accesso',(!id?input('email','Email','','email','required'):'')+input('password',id?'Nuova password (facoltativa)':'Password','','password',`minlength="12" ${id?'':'required'} autocomplete="new-password"`)+select('role','Ruolo',[['admin','Amministratore'],['operator','Operatore']],role)+(id?check('active','Accesso attivo',active):''),async(v,f)=>{if(demo)throw Error('Gestione utenti disponibile dopo la configurazione online');await api('user-save',{...v,id,active:id?f.elements.active.checked:true});render()})}
function settings(){C.innerHTML=`<h1>Calendario e impostazioni</h1><div class="card"><h2>Collega il calendario con Zapier</h2><p>Stato: integrazione esterna da configurare. “Sincronizza” rilegge gli eventi già ricevuti dal server, senza forzare i tempi di esecuzione di Zapier.</p><ol><li>Identifica l’account del calendario nell’app Calendario Apple: iCloud, Google oppure Outlook.</li><li>Se usi Google nell’app Apple, crea in Zapier un flusso “Google Calendar → New or Updated Event”. Per un calendario iCloud nativo serve prima definire un collegamento compatibile: non rendere pubblico il calendario dei pazienti.</li><li>Aggiungi “Webhooks by Zapier → POST” con URL <code>${esc(location.origin)}/api/app?action=calendar-hook</code>.</li><li>Imposta il formato JSON e l’intestazione Authorization: Bearer seguita dal segreto CALENDAR_WEBHOOK_SECRET configurato su Vercel.</li><li>Mappa externalId, title, start, end. Usa date ISO complete di fuso orario. Importa solo titoli neutri, per esempio “Occupato”.</li><li>Esegui il test, pubblica lo Zap, poi premi Sincronizza. Crea un secondo flusso per gli eventi cancellati, inviando lo stesso externalId e cancelled: true.</li></ol><p>Gli eventi importati diventano impegni personali e bloccano gli orari. Un conflitto viene rifiutato e segnalato da Zapier. Il collegamento in ingresso non invia appuntamenti del gestionale ad Apple.</p><p><a href="https://zapier.com/app/zaps" target="_blank" rel="noopener">Apri Zapier</a> · <a href="https://zapier.com/apps/google-calendar/integrations" target="_blank" rel="noopener">Guida integrazione Google Calendar</a></p>${btn('Sincronizza','sync()')}${btn('Esporta calendario iCal (.ics)','exportIcal()')}<p>L’esportazione iCal è una copia degli eventi, con titoli anonimi. Non è un abbonamento con aggiornamento automatico.</p></div>`}
function exportIcal(){const stamp=d=>new Date(d).toISOString().replace(/[-:]/g,'').replace(/\.\d{3}Z/,'Z');const lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Studio Rocchi//Agenda//IT'];for(const r of list('appointments').filter(r=>!r.data.cancelled)){lines.push('BEGIN:VEVENT','UID:'+r.id+'@studio-rocchi','DTSTAMP:'+stamp(new Date()),'DTSTART:'+stamp(r.data.start),'DTEND:'+stamp(r.data.end),'SUMMARY:Occupato','END:VEVENT')}lines.push('END:VCALENDAR');const a=document.createElement('a'),url=URL.createObjectURL(new Blob([lines.join('\r\n')+'\r\n'],{type:'text/calendar'}));a.href=url;a.download='studio-rocchi.ics';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function render(){if(!user)return;document.querySelector('[data-page=accessi]').hidden=user.role!=='admin';if(current==='home')return home();if(current==='agenda')return agenda();if(current==='pazienti')return patientsPage();if(current==='pagamenti')return payments();if(current==='accessi')return accessPage();if(current==='impostazioni')return settings();if(current==='promemoria'){C.innerHTML=`<h1>Promemoria</h1><div class="toolbar">${btn('Attivi',"archive=false;render()",!archive?'primary':'ghost')}${btn('Archiviati',"archive=true;render()",archive?'primary':'ghost')}${btn('Nuovo','reminder()')}${archive?btn('Elimina selezionati','deleteReminders()'):''}</div><div class="card">${archive?'<label><input type="checkbox" onchange="document.querySelectorAll(\'.archive-select\').forEach(x=>x.checked=this.checked)"> Seleziona tutti</label>':''}${reminders(archive)}</div>`;return}if(current==='documenti'){C.innerHTML=`<h1>Documenti</h1><div class="card">${docRows(list('documents'))}</div>`;return}C.innerHTML='<h1>'+esc(current)+'</h1><p>Questa sezione della versione precedente non contiene ancora funzionalità operative.</p>'}
function search(q){q=q.trim().toLocaleLowerCase('it');if(!q){render();return}C.innerHTML=`<h1>Risultati ricerca</h1><div class="card">${records.filter(r=>[r.kind==='patients'?full(r):'',r.data.title,r.data.name,r.kind==='appointments'?title(r):'',r.data.taxCode,r.data.email,r.data.note].some(v=>String(v||'').toLocaleLowerCase('it').includes(q))).map(r=>`<div>${btn(esc(r.kind==='patients'?full(r):r.kind==='appointments'?title(r):r.data.title||r.data.name),r.kind==='patients'?`patient('${r.id}')`:r.kind==='appointments'?`appointment('${r.id}')`:r.kind==='documents'?`downloadDoc('${r.id}')`:`reminder('${r.id}')`)} <small>${({patients:'Paziente',appointments:'Appuntamento',documents:'Documento',reminders:'Promemoria'})[r.kind]}</small></div>`).join('')||'<p>Nessun risultato.</p>'}</div>`}
function demoStart(){demo=true;user={id:crypto.randomUUID(),email:'demo@studio.example',role:'admin',active:true};const p=rec('patients',{firstName:'Anna',lastName:'Esempio',fee:65,site:'Parma',mode:'In presenza',consent:false});records=[p,rec('appointments',{patientId:p.id,start:new Date(today()+'T09:00').toISOString(),end:new Date(today()+'T10:00').toISOString(),fee:65,payment:'due',site:'Parma',personal:false}),rec('reminders',{title:'Esempio: controllare il calendario',date:today(),done:false})];document.getElementById('auth').hidden=true;document.querySelector('.shell').hidden=false;document.getElementById('demo-banner').hidden=false;render()}
async function boot(){const consentToken=typeof URLSearchParams!=='undefined'?new URLSearchParams(location.search).get('consent'):null;if(consentToken){await publicConsent(consentToken);return}document.getElementById('public-consent').hidden=true;document.querySelector('.shell').hidden=true;document.getElementById('auth').hidden=false;try{const c=await api('config');document.getElementById('setup-note').textContent=c.configured?'Accedi con le credenziali assegnate dall’amministratore.':'Archivio online da attivare: segui ATTIVAZIONE.md incluso nel progetto. Puoi esplorare la demo temporanea.';if(c.configured){try{const s=await api('state');user=s.user;records=s.records;document.getElementById('auth').hidden=true;document.querySelector('.shell').hidden=false;render()}catch{}}}catch(e){document.getElementById('setup-note').textContent=e.message}}
document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>{document.getElementById('search').value='';page(b.dataset.page)});document.querySelector('.close').onclick=closeM;M.onclick=e=>{if(e.target===M)closeM()};document.addEventListener('keydown',e=>{if(e.key==='Escape')closeM()});document.getElementById('search').oninput=e=>search(e.target.value);document.getElementById('login-form').onsubmit=async e=>{e.preventDefault();const f=e.target;try{await api('login',Object.fromEntries(new FormData(f)));f.reset();await boot()}catch(err){document.getElementById('login-error').textContent=err.message}};document.getElementById('logout').onclick=async()=>{try{if(!demo)await api('logout',{});demo=false;records=[];user=null;closeM();C.innerHTML='';document.getElementById('demo-banner').hidden=true;await boot()}catch(e){notice(e.message)}};boot();
